import fs12 from "fs";
import os3 from "os";
import path56 from "path";
var CREDENTIALS_DIR = path56.join(os3.homedir(), ".archsetu");
var CREDENTIALS_FILE = path56.join(CREDENTIALS_DIR, "sites.json");
function storeKey(projectDir) {
  const resolved = path56.resolve(projectDir);
  return process.platform === "linux" ? resolved : resolved.toLowerCase();
}
function readStore() {
  try {
    const parsed = JSON.parse(fs12.readFileSync(CREDENTIALS_FILE, "utf8"));
    return typeof parsed === "object" && parsed !== null ? parsed : {};
  } catch {
    return {};
  }
}
function rememberedSite(projectDir) {
  const entry = readStore()[storeKey(projectDir)];
  if (!entry || typeof entry.slug !== "string" || typeof entry.publishKey !== "string") return null;
  return entry;
}
function rememberSite(projectDir, credential) {
  try {
    fs12.mkdirSync(CREDENTIALS_DIR, { recursive: true });
    const store = readStore();
    store[storeKey(projectDir)] = credential;
    fs12.writeFileSync(CREDENTIALS_FILE, `${JSON.stringify(store, null, 2)}
`, { mode: 384 });
    try {
      fs12.chmodSync(CREDENTIALS_FILE, 384);
    } catch {
    }
  } catch {
  }
}
var CREDENTIALS_PATH = CREDENTIALS_FILE;
var UPLOAD_CONCURRENCY = 6;
var UPLOAD_TIMEOUT_MS = 12e4;
var UPLOAD_ATTEMPTS = 3;
var CONTENT_TYPES = {
  html: "text/html",
  htm: "text/html",
  css: "text/css",
  js: "text/javascript",
  mjs: "text/javascript",
  cjs: "text/javascript",
  json: "application/json",
  webmanifest: "application/manifest+json",
  map: "application/json",
  txt: "text/plain",
  md: "text/plain",
  csv: "text/csv",
  xml: "application/xml",
  svg: "image/svg+xml",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  avif: "image/avif",
  bmp: "image/bmp",
  ico: "image/x-icon",
  woff: "font/woff",
  woff2: "font/woff2",
  ttf: "font/ttf",
  otf: "font/otf",
  eot: "application/vnd.ms-fontobject",
  mp4: "video/mp4",
  webm: "video/webm",
  ogg: "audio/ogg",
  mp3: "audio/mpeg",
  wav: "audio/wav",
  pdf: "application/pdf",
  wasm: "application/wasm"
};
function contentTypeOf(filePath) {
  const extension = filePath.slice(filePath.lastIndexOf(".") + 1).toLowerCase();
  return CONTENT_TYPES[extension] ?? "application/octet-stream";
}
async function putFile(url, file) {
  for (let attempt = 1; attempt <= UPLOAD_ATTEMPTS; attempt++) {
    try {
      const res = await fetch(url, {
        method: "PUT",
        headers: { "content-type": contentTypeOf(file.path), "x-upsert": "true" },
        body: fs12.readFileSync(file.absolutePath),
        signal: AbortSignal.timeout(UPLOAD_TIMEOUT_MS)
      });
      if (res.ok) return null;
      const body = (await res.text().catch(() => "")).slice(0, 160);
      if (res.status < 500) return `${file.path}: ${res.status} ${body}`;
      if (attempt === UPLOAD_ATTEMPTS) return `${file.path}: ${res.status} ${body}`;
    } catch (err) {
      if (attempt === UPLOAD_ATTEMPTS) return `${file.path}: ${err.message}`;
    }
    await new Promise((resolve) => setTimeout(resolve, 400 * attempt));
  }
  return null;
}
async function uploadFiles(uploads, files, onProgress) {
  const byPath = new Map(files.map((file) => [file.path, file]));
  let done = 0;
  let failure = null;
  const queue = [...uploads];
  const worker = async () => {
    for (; ; ) {
      if (failure !== null) return;
      const next = queue.shift();
      if (!next) return;
      const file = byPath.get(next.path);
      if (!file) {
        failure = `${next.path} disappeared while uploading.`;
        return;
      }
      const error = await putFile(next.url, file);
      if (error) {
        failure = error;
        return;
      }
      done++;
      onProgress({ done, total: uploads.length });
    }
  };
  await Promise.all(
    Array.from({ length: Math.min(UPLOAD_CONCURRENCY, queue.length) }, () => worker())
  );
  return failure;
}

